  "url": "https://hooks.slack.com/services/T000/B000/XXXX",
  "payload": {"text": "New meeting analyzed: 3 action items, ships Friday"},
  "target": null,            // "slack" | "zapier" | "n8n" | "generic" — auto-detected from url if omitted
